-- Event management sample database (event-management-sample-database) v1 — sqlite
-- Synthetic sample data, CC0-1.0. Deterministic: the same spec and seed produce this byte for byte.
-- seed: flagship:event-management-sample-database:1k
-- Engine 2 (faker 10.6.0), locale en_GB. UTF-8.
-- Tables in dependency order; foreign keys are added after the data.

BEGIN;

CREATE TABLE "categories" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "description" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE
);

CREATE TABLE "coupons" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "code" TEXT NOT NULL UNIQUE,
    "discount_type" TEXT NOT NULL,
    "discount_value" INTEGER NOT NULL,
    "expiration_date" TEXT,
    "max_uses" INTEGER
);

CREATE TABLE "equipment" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "name" TEXT NOT NULL,
    "serial_number" TEXT NOT NULL UNIQUE,
    "status" TEXT NOT NULL,
    "type" TEXT NOT NULL
);

CREATE TABLE "roles" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "description" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE
);

CREATE TABLE "sponsors" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "logo_url" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE,
    "website" TEXT NOT NULL
);

CREATE TABLE "users" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "email" TEXT NOT NULL UNIQUE,
    "first_name" TEXT NOT NULL,
    "last_name" TEXT NOT NULL,
    "password_hash" TEXT NOT NULL,
    "phone" TEXT NOT NULL
);

CREATE TABLE "notifications" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "is_read" INTEGER NOT NULL,
    "message" TEXT NOT NULL,
    "sent_time" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "profiles" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "bio" TEXT,
    "company" TEXT NOT NULL,
    "job_title" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL UNIQUE,
    "website" TEXT,
    FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "speakers" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "biography" TEXT NOT NULL,
    "organization" TEXT NOT NULL,
    "position" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "user_roles" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "role_id" INTEGER NOT NULL,
    "user_id" INTEGER NOT NULL UNIQUE,
    FOREIGN KEY ("role_id") REFERENCES "roles" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "vendors" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "contact_name" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE,
    "phone" TEXT NOT NULL,
    "service_type" TEXT NOT NULL
);

CREATE TABLE "venues" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "address" TEXT NOT NULL,
    "capacity" INTEGER NOT NULL,
    "city" TEXT NOT NULL,
    "country" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE,
    "postal_code" TEXT NOT NULL,
    "state" TEXT NOT NULL
);

CREATE TABLE "booths" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "label" TEXT NOT NULL,
    "size" TEXT NOT NULL,
    "venue_id" INTEGER NOT NULL,
    FOREIGN KEY ("venue_id") REFERENCES "venues" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "events" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "description" TEXT NOT NULL,
    "end_time" TEXT NOT NULL,
    "organizer_id" INTEGER NOT NULL,
    "start_time" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "venue_id" INTEGER NOT NULL,
    FOREIGN KEY ("organizer_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("venue_id") REFERENCES "venues" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "event_categories" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "category_id" INTEGER NOT NULL,
    "event_id" INTEGER NOT NULL,
    FOREIGN KEY ("category_id") REFERENCES "categories" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("event_id") REFERENCES "events" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "event_vendors" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "contract_details" TEXT NOT NULL,
    "cost" NUMERIC(14,2) NOT NULL,
    "event_id" INTEGER NOT NULL,
    "vendor_id" INTEGER NOT NULL,
    FOREIGN KEY ("event_id") REFERENCES "events" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("vendor_id") REFERENCES "vendors" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "exhibitors" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "company_name" TEXT NOT NULL,
    "description" TEXT NOT NULL,
    "event_id" INTEGER NOT NULL,
    "website" TEXT NOT NULL,
    FOREIGN KEY ("event_id") REFERENCES "events" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "booth_assignments" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "assigned_at" TEXT NOT NULL,
    "booth_id" INTEGER NOT NULL,
    "exhibitor_id" INTEGER NOT NULL UNIQUE,
    FOREIGN KEY ("booth_id") REFERENCES "booths" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("exhibitor_id") REFERENCES "exhibitors" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "feedbacks" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "comments" TEXT,
    "event_id" INTEGER NOT NULL,
    "rating" INTEGER NOT NULL,
    "submitted_at" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("event_id") REFERENCES "events" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "media" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "event_id" INTEGER NOT NULL,
    "file_path" TEXT NOT NULL,
    "file_type" TEXT NOT NULL,
    "uploaded_at" TEXT NOT NULL,
    "uploaded_by" INTEGER NOT NULL,
    FOREIGN KEY ("event_id") REFERENCES "events" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("uploaded_by") REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "rooms" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "capacity" INTEGER NOT NULL,
    "floor" INTEGER NOT NULL,
    "name" TEXT NOT NULL,
    "venue_id" INTEGER NOT NULL,
    FOREIGN KEY ("venue_id") REFERENCES "venues" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "sessions" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "description" TEXT NOT NULL,
    "end_time" TEXT NOT NULL,
    "event_id" INTEGER NOT NULL,
    "room_id" INTEGER NOT NULL,
    "start_time" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    FOREIGN KEY ("event_id") REFERENCES "events" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("room_id") REFERENCES "rooms" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "session_equipment" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "equipment_id" INTEGER NOT NULL,
    "quantity" INTEGER NOT NULL,
    "session_id" INTEGER NOT NULL,
    FOREIGN KEY ("equipment_id") REFERENCES "equipment" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("session_id") REFERENCES "sessions" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "session_speakers" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "session_id" INTEGER NOT NULL,
    "speaker_id" INTEGER NOT NULL,
    FOREIGN KEY ("session_id") REFERENCES "sessions" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("speaker_id") REFERENCES "speakers" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "sponsorship_packages" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "benefits" TEXT NOT NULL,
    "cost" NUMERIC(14,2) NOT NULL,
    "event_id" INTEGER NOT NULL,
    "name" TEXT NOT NULL,
    FOREIGN KEY ("event_id") REFERENCES "events" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "event_sponsors" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "event_id" INTEGER NOT NULL,
    "package_id" INTEGER NOT NULL,
    "sponsor_id" INTEGER NOT NULL,
    FOREIGN KEY ("package_id") REFERENCES "sponsorship_packages" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("sponsor_id") REFERENCES "sponsors" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "tasks" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "description" TEXT NOT NULL,
    "due_date" TEXT NOT NULL,
    "event_id" INTEGER NOT NULL,
    "status" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    FOREIGN KEY ("event_id") REFERENCES "events" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "staff_assignments" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "assigned_at" TEXT NOT NULL,
    "task_id" INTEGER NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("task_id") REFERENCES "tasks" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "tickets" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "event_id" INTEGER NOT NULL,
    "name" TEXT NOT NULL,
    "price" NUMERIC(14,2) NOT NULL,
    "quantity_available" INTEGER NOT NULL,
    "sale_end" TEXT NOT NULL,
    "sale_start" TEXT NOT NULL,
    FOREIGN KEY ("event_id") REFERENCES "events" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "registrations" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "registration_time" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "ticket_id" INTEGER NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("ticket_id") REFERENCES "tickets" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "applied_coupons" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "coupon_id" INTEGER NOT NULL,
    "registration_id" INTEGER NOT NULL UNIQUE,
    FOREIGN KEY ("coupon_id") REFERENCES "coupons" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("registration_id") REFERENCES "registrations" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "checkins" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "checkin_time" TEXT NOT NULL,
    "gate_keeper_id" INTEGER NOT NULL,
    "registration_id" INTEGER NOT NULL UNIQUE,
    FOREIGN KEY ("gate_keeper_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("registration_id") REFERENCES "registrations" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "payments" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "amount" NUMERIC(14,2) NOT NULL,
    "payment_method" TEXT NOT NULL,
    "payment_time" TEXT NOT NULL,
    "registration_id" INTEGER NOT NULL UNIQUE,
    "status" TEXT NOT NULL,
    "transaction_reference" TEXT NOT NULL UNIQUE,
    FOREIGN KEY ("registration_id") REFERENCES "registrations" ("id") DEFERRABLE INITIALLY DEFERRED
);

